from pathlib import Path
import json,html,re
V=Path(__file__).resolve().parent
plan=json.loads((V/'scene-plan.json').read_text(encoding='utf-8'))
duration=plan[-1]['end']
fonts='''@font-face{font-family:Barlow;src:url('assets/fonts/barlow-bold.ttf');font-weight:700}@font-face{font-family:Barlow;src:url('assets/fonts/barlow-black.ttf');font-weight:900}@font-face{font-family:Barlow;src:url('assets/fonts/barlow-regular.ttf');font-weight:400}@font-face{font-family:'IBM Plex Mono';src:url('assets/fonts/ibm-plex-mono.ttf');font-weight:400}'''
hosts=[]
for i,s in enumerate(plan):
    id=s['id'];title=html.escape(s['title']);n=i+1
    content=f'''<template><style>#root{{position:absolute;inset:0;color:#173B42}}.rail-title{{position:absolute;left:72px;top:250px;width:820px;margin:0;font:900 72px/1.02 Barlow,sans-serif;letter-spacing:-1.3px;background:#FFF5DE;padding:14px 22px;width:max-content;max-width:820px;box-decoration-break:clone}}.rail-line{{position:absolute;left:72px;top:440px;width:105px;height:7px;background:#CCA84F}}</style><div id="root" data-composition-id="{id}" data-width="1080" data-height="1920" data-duration="{s['duration']:.6f}"><div id="title-clip-{n}" class="clip" data-start="0" data-duration="{s['duration']:.6f}" data-track-index="1"><h1 class="rail-title" id="title-{n}">{title}</h1><div class="rail-line" id="line-{n}"></div></div></div><script>const tl=gsap.timeline({{paused:true}});tl.fromTo('#title-{n}',{{opacity:0,y:18}},{{opacity:1,y:0,duration:.24,ease:'power2.out'}},0);tl.fromTo('#line-{n}',{{scaleX:0,transformOrigin:'left center'}},{{scaleX:1,duration:.3,ease:'power2.out'}},.14);window.__timelines['{id}']=tl;</script></template>'''
    (V/f'compositions/frames/{id}.html').write_text(content,encoding='utf-8')
    hosts.append(f'<div id="scene-{n}" class="clip" data-composition-id="{id}" data-composition-src="compositions/frames/{id}.html" data-start="{s["start"]:.6f}" data-duration="{s["duration"]:.6f}" data-width="1080" data-height="1920" data-track-index="1" data-track-kind="graphics" data-beat="{s["title"]}" style="z-index:2"></div>')
audio='';caption=''
if (V/'timing.json').exists():
    timing=json.loads((V/'timing.json').read_text(encoding='utf-8'))
    audio=f'<audio id="narration" src="assets/audio/narration-master.wav" data-start="0.25" data-duration="{timing["voice_duration"]:.6f}" data-volume="1" data-track-index="10"></audio>'
    caption=f'<div id="caption-host" class="clip" data-composition-id="captions" data-composition-src="compositions/captions.html" data-start="0" data-duration="{duration:.6f}" data-width="1080" data-height="1920" data-track-index="3" data-track-kind="captions" style="z-index:4"></div>'
txt=f'''<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=1080,height=1920"><title>Rel bukan dua batang besi</title><script src="vendor/gsap.min.js"></script><script src="scene-data.js"></script><style>{fonts}*{{box-sizing:border-box}}html,body{{margin:0;width:100%;height:100%;font-family:Barlow,sans-serif;background:#C5D5D8;color:#173B42}}#root{{position:relative;width:100%;height:100%;overflow:hidden}}.clip{{position:absolute;inset:0}}#rail-world{{display:block;width:100%;height:100%}}.series{{position:absolute;left:72px;top:185px;font-size:30px;font-weight:900;letter-spacing:.8px;border-left:10px solid #CCA84F;padding:7px 16px 7px 18px;background:#FFF5DE;z-index:3}}#schematic-note{{position:absolute;left:72px;top:1065px;padding:10px 17px;font-size:30px;font-weight:700;background:#FFF5DE;border-left:6px solid #E56E43;z-index:3}}.context{{position:absolute;left:72px;top:1390px;font-size:28px;font-weight:700;z-index:3;background:#FFF5DEb8;padding:6px 10px}}</style></head><body><div id="root" data-composition-id="railway" data-width="1080" data-height="1920" data-duration="{duration:.6f}"><canvas id="rail-world" class="clip" data-start="0" data-duration="{duration:.6f}" data-track-index="0" data-layout-allow-overlap="true"></canvas><div class="series">BONGKAR SISTEM</div>{''.join(hosts)}<div id="schematic-note">Skema gaya / aliran</div><div class="context">Visualisasi fungsi · bukan urutan konstruksi</div>{caption}{audio}</div><script type="module" src="world.js"></script><script>const tl=gsap.timeline({{paused:true}});tl.to({{}},{{duration:{duration:.6f}}});window.__timelines['railway']=tl;</script></body></html>'''
(V/'index.html').write_text(txt,encoding='utf-8')
(V/'scene-data.js').write_text('window.RAIL_PLAN='+json.dumps(plan,ensure_ascii=False)+';\nwindow.RAIL_DURATION='+str(duration)+';\n',encoding='utf-8')
print(json.dumps(dict(duration=duration,scenes=len(plan),audio=bool(audio))))
